<script setup lang="ts">
import {computed} from 'vue';
import {REPORT_COLUMNS,type ReportResult} from '~~/shared/types/upts-reports';
const props=defineProps<{result:ReportResult}>();const emit=defineEmits<{object:[id:number];work:[id:number]}>();
const columns=computed(()=>props.result.config.columns.map(k=>REPORT_COLUMNS[props.result.config.source].find(c=>c.key===k)!));
const groups=computed(()=>props.result.groups.slice((props.result.page-1)*props.result.pageSize,props.result.page*props.result.pageSize));
</script>
<template><div class="report-table work-table-wrap"><table v-if="result.config.mode==='summary'"><thead><tr><th>Группа</th><th>Строк</th><template v-if="result.config.source!=='documents'"><th>Работ</th><th>Выполнено</th><th>Просрочено</th><th>Готовность</th></template></tr></thead><tbody><tr v-for="g in groups" :key="g.name"><td>{{ g.name }}</td><td>{{ g.count }}</td><template v-if="result.config.source!=='documents'"><td>{{ g.workCount }}</td><td>{{ g.done }}</td><td>{{ g.overdue }}</td><td>{{ g.percent===null?'—':g.percent+'%' }}</td></template></tr></tbody></table>
<table v-else><thead><tr><th v-for="c in columns" :key="c.key">{{ c.label }}</th></tr></thead><tbody><template v-for="(r,index) in result.rows" :key="r.id"><tr v-if="result.config.group!=='none'&&(index===0||result.rows[index-1]?.group!==r.group)" class="report-group"><td :colspan="columns.length">{{ r.group }}</td></tr><tr><td v-for="c in columns" :key="c.key"><button v-if="c.key==='object'" class="report-link" @click="emit('object',r.objectId)">{{ r.values[c.key] }}</button><button v-else-if="r.taskId&&((c.key==='name'&&result.config.source==='works')||c.key==='work')" class="report-link" @click="emit('work',r.taskId)">{{ r.values[c.key] }}</button><span v-else>{{ r.values[c.key]===0?0:r.values[c.key]||'—' }}</span></td></tr></template></tbody></table><p v-if="!result.total" class="work-muted">По выбранным условиям данных нет.</p></div></template>
<style scoped>.report-table{overflow:auto;min-width:0}.report-table table{width:100%;border-collapse:collapse}.report-table :is(th,td){padding:8px;text-align:left;font-size:12px;border-bottom:1px solid var(--work-line);vertical-align:top;min-width:70px}.report-table th{color:var(--work-muted);position:sticky;top:0;background:var(--work-panel);z-index:1}.report-group td{font-weight:600;background:color-mix(in srgb,var(--work-accent) 7%,var(--work-panel))}.report-table .report-link{border:0;padding:0;background:none;color:var(--work-accent);text-align:left;text-decoration:underline;min-height:0}</style>
